export function ScalarControl({
  kind,
  schema,
  field,
  textInput,
  compact = false,
  nullable = false,
  ...controlProps
}: {
  kind: FieldKind
  schema: Schema
  field: ControlFieldApi
  textInput?: JsonFormTextInput
  /** Dense, single-line variant for table cells. */
  compact?: boolean
  nullable?: boolean
} & ScalarControlDomProps) {
  if (kind === "enum") {
    return (
      <EnumControl
        {...controlProps}
        schema={schema}
        field={field}
        compact={compact}
        nullable={nullable}
      />
    )
  }

  if (kind === "number" || kind === "integer") {
    return (
      <NumberControl
        {...controlProps}
        kind={kind}
        field={field}
        compact={compact}
        nullable={nullable}
      />
    )
  }

  if (
    schema.format === "date" ||
    schema.format === "time" ||
    schema.format === "date-time"
  ) {
    return (
      <DateTimeScalarControl
        {...controlProps}
        kind={schema.format as DateTimeControlKind}
        field={field}
        compact={compact}
        nullable={nullable}
      />
    )
  }

  return (
    <TextControl
      {...controlProps}
      schema={schema}
      field={field}
      textInput={textInput}
      compact={compact}
      nullable={nullable}
    />
  )
}

