import * as React from "react"

import { getFixedGridRowWindowStyle } from "@/components/ui/fixed-grid-layout"
import { useFixedRowVirtualization } from "@/components/ui/fixed-grid-virtualization"
import { joinJsonFormPath } from "@/components/json-form/path-codec"
import {
  TABLE_JUMP_ROW_OVERSCAN,
  TABLE_MAX_HEIGHT,
  TABLE_ROW_HEIGHT,
  TABLE_ROW_OVERSCAN,
} from "@/components/json-form/table/array-table-config"
import {
  useArrayTableScrollActivity,
  type ArrayTableScrollHandlers,
} from "@/components/json-form/table/array-table-scroll"

type ArrayTableField = { id: string }

export function StaticArrayTableBody({
  fields,
  scrollHandlers,
  renderItem,
}: {
  fields: ArrayTableField[]
  scrollHandlers: ArrayTableScrollHandlers
  renderItem: (index: number) => React.ReactNode
}) {
  const scrollRef = React.useRef<HTMLDivElement>(null)
  useArrayTableScrollActivity(scrollRef, scrollHandlers)

  return (
    <div
      ref={scrollRef}
      data-slot="json-form-table-scroll"
      className="overflow-y-auto"
      style={{ maxHeight: TABLE_MAX_HEIGHT }}
    >
      <div className="[contain:layout_paint_style]">
        {fields.map((entry, index) => (
          <React.Fragment key={entry.id}>{renderItem(index)}</React.Fragment>
        ))}
      </div>
    </div>
  )
}

export function FixedArrayTableBody({
  name,
  fields,
  activeEditorPath,
  scrollHandlers,
  renderItem,
}: {
  name: string
  fields: ArrayTableField[]
  activeEditorPath: string | null
  scrollHandlers: ArrayTableScrollHandlers
  renderItem: (index: number, rowTopPx: number) => React.ReactNode
}) {
  const scrollRef = React.useRef<HTMLDivElement>(null)
  const { virtualRows, totalRowSize } = useFixedRowVirtualization({
    rowCount: fields.length,
    rowSize: TABLE_ROW_HEIGHT,
    rowOverscan: TABLE_ROW_OVERSCAN,
    jumpRowOverscan: TABLE_JUMP_ROW_OVERSCAN,
    scrollRef,
  })
  useArrayTableScrollActivity(scrollRef, scrollHandlers)

  return (
    <div
      ref={scrollRef}
      data-slot="json-form-table-scroll"
      className="overflow-y-auto"
      style={{ maxHeight: TABLE_MAX_HEIGHT }}
    >
      <div
        style={getFixedGridRowWindowStyle({
          height: totalRowSize,
          minWidth: "100%",
        })}
        className="[contain:layout_paint_style]"
      >
        {virtualRows.map((virtualRow, slotIndex) => {
          const isEditingRow = activeEditorPath?.startsWith(
            `${joinJsonFormPath(name, virtualRow.index)}.`
          )
          return (
            <React.Fragment
              key={
                isEditingRow ? fields[virtualRow.index].id : `slot-${slotIndex}`
              }
            >
              {renderItem(virtualRow.index, virtualRow.start)}
            </React.Fragment>
          )
        })}
      </div>
    </div>
  )
}

import {
  type DataCellCommitValue,
  type DataCellValueMeta,
} from "@/components/ui/data-cell"
import { datetimeLocalInputValue } from "@/components/json-form/scalar-control"
import type { Column } from "@/components/json-form/schema-model"

export type SetArrayTableCellValue = (
  path: string,
  value: unknown,
  options: {
    shouldDirty: true
    shouldTouch: true
    shouldValidate: true
  }
) => void

export type CommitArrayTableCellValue = (
  value: DataCellCommitValue,
  meta?: DataCellValueMeta
) => void

export const NO_ARRAY_TABLE_CELL_COMMIT = Symbol("NO_ARRAY_TABLE_CELL_COMMIT")

export function normalizeArrayTableCellValue({
  column,
  currentValue,
  nextValue,
  meta,
}: {
  column: Column
  currentValue: unknown
  nextValue: DataCellCommitValue
  meta?: DataCellValueMeta
}): unknown | typeof NO_ARRAY_TABLE_CELL_COMMIT {
  let normalizedValue: unknown
  if (column.kind === "number" || column.kind === "integer") {
    if (meta && !meta.isValid) return NO_ARRAY_TABLE_CELL_COMMIT
    normalizedValue =
      typeof nextValue === "number"
        ? nextValue
        : nextValue === null && column.nullable && meta?.isEmpty !== false
          ? null
          : undefined
    if (normalizedValue === undefined) return NO_ARRAY_TABLE_CELL_COMMIT
  } else if (column.kind === "boolean") {
    normalizedValue = Boolean(nextValue)
  } else {
    const currentText = currentValue == null ? "" : String(currentValue)
    const currentDisplay =
      column.schema.format === "date-time"
        ? datetimeLocalInputValue(currentText)
        : currentText
    const nextText = typeof nextValue === "string" ? nextValue : ""
    const nextDisplay =
      column.schema.format === "date-time"
        ? datetimeLocalInputValue(nextText)
        : nextText

    if (nextDisplay === currentDisplay) return NO_ARRAY_TABLE_CELL_COMMIT
    normalizedValue = nextDisplay === "" && column.nullable ? null : nextDisplay
  }

  return Object.is(currentValue, normalizedValue)
    ? NO_ARRAY_TABLE_CELL_COMMIT
    : normalizedValue
}

export function commitArrayTableCellValue({
  column,
  currentValue,
  meta,
  nextValue,
  path,
  setValue,
}: {
  column: Column
  currentValue: unknown
  meta?: DataCellValueMeta
  nextValue: DataCellCommitValue
  path: string
  setValue: SetArrayTableCellValue
}) {
  const normalizedValue = normalizeArrayTableCellValue({
    column,
    currentValue,
    nextValue,
    meta,
  })

  if (normalizedValue === NO_ARRAY_TABLE_CELL_COMMIT) return
  setValue(path, normalizedValue, {
    shouldDirty: true,
    shouldTouch: true,
    shouldValidate: true,
  })
}

import { cn } from "@/lib/utils"
import type { CommitArrayTableCellValue } from "@/components/json-form/table/array-table-cell-commit"
import type { ArrayTableCellModel } from "@/components/json-form/table/array-table-cell-model"

export function arrayTableCellClassName(model: ArrayTableCellModel): string {
  return cn(
    "min-w-0 rounded data-[source-active=true]:bg-primary/5 data-[source-active=true]:ring-1 data-[source-active=true]:ring-primary/30",
    !model.isEditing && !model.isScalarEditing
      ? "hover:bg-background focus-visible:bg-background focus-visible:ring-1 focus-visible:ring-ring/30"
      : "px-1 py-0.5",
    model.sourceLinked &&
      (model.isEditing || model.isScalarEditing) &&
      "hover:bg-muted/55"
  )
}

export function arrayTableCellProps(model: ArrayTableCellModel) {
  return {
    "data-slot": "data-cell",
    "data-table-cell": "",
    "data-source-path": model.sourceLinked ? model.sourcePath : undefined,
    className: arrayTableCellClassName(model),
  }
}

export function editableArrayTableCellProps({
  closeEditor,
  commitValue,
  model,
}: {
  closeEditor: () => void
  commitValue: CommitArrayTableCellValue
  model: ArrayTableCellModel
}) {
  return {
    active: model.isScalarEditing,
    editable: model.isScalarEditing,
    role: !model.isScalarEditing ? "button" : undefined,
    "aria-label": `${model.label} ${model.displayText}`,
    tabIndex: 0,
    "data-table-cell-editable": !model.isScalarEditing ? "true" : undefined,
    "data-table-cell-path": !model.isScalarEditing ? model.path : undefined,
    autoFocus: model.isScalarEditing,
    name: model.path,
    onCommit: commitValue,
    "data-table-cell-editor": model.isScalarEditing ? "true" : undefined,
    onBlur: () => {
      if (model.isScalarEditing) closeEditor()
    },
  }
}

"use client"

import * as React from "react"
import { useController, useFormContext } from "react-hook-form"

import { cn } from "@/lib/utils"
import { DataCell } from "@/components/ui/data-cell"
import {
  dataCellNumberValue,
  dataCellTextValue,
  ScalarControl,
} from "@/components/json-form/scalar-control"
import type { Column } from "@/components/json-form/schema-model"
import {
  commitArrayTableCellValue,
  type CommitArrayTableCellValue,
  type SetArrayTableCellValue,
} from "@/components/json-form/table/array-table-cell-commit"
import type { ArrayTableCellModel } from "@/components/json-form/table/array-table-cell-model"
import {
  arrayTableCellClassName,
  arrayTableCellProps,
  editableArrayTableCellProps,
} from "@/components/json-form/table/array-table-cell-props"

export function ArrayTableCell({
  model,
  column,
  setValue,
  closeEditor,
}: {
  model: ArrayTableCellModel
  column: Column
  setValue: SetArrayTableCellValue
  closeEditor: () => void
}) {
  const cellClassName = arrayTableCellClassName(model)
  const cellProps = arrayTableCellProps(model)
  const commitValue = React.useCallback<CommitArrayTableCellValue>(
    (nextValue, meta) => {
      commitArrayTableCellValue({
        column,
        currentValue: model.value,
        meta,
        nextValue,
        path: model.path,
        setValue,
      })
    },
    [column, model.path, model.value, setValue]
  )
  const editableProps = editableArrayTableCellProps({
    model,
    commitValue,
    closeEditor,
  })

  if (model.isEditing) {
    return (
      <ArrayTableCellEditor
        path={model.path}
        column={column}
        onClose={closeEditor}
        cellProps={cellProps}
      />
    )
  }

  if (model.isEnum) {
    return (
      <DataCell
        {...cellProps}
        kind="text"
        value={dataCellTextValue(model.value)}
        formatValue={() => model.displayText}
        placeholder=""
        role="button"
        tabIndex={0}
        aria-label={`${model.label} ${model.displayText}`}
        data-table-cell-editable="true"
        data-table-cell-path={model.path}
        className={cn(cellClassName, "text-sm")}
      />
    )
  }

  if (model.kind === "number" || model.kind === "integer") {
    return (
      <DataCell
        {...cellProps}
        {...editableProps}
        kind={model.kind}
        value={dataCellNumberValue(model.value)}
        formatValue={() => model.displayText}
        placeholder=""
        className={cn(cellClassName, "text-sm")}
      />
    )
  }

  if (model.kind === "boolean") {
    return (
      <DataCell
        {...cellProps}
        {...editableProps}
        kind="boolean"
        value={Boolean(model.value)}
        className={cn(cellClassName, "text-sm")}
      />
    )
  }

  return (
    <DataCell
      {...cellProps}
      {...editableProps}
      kind={model.kind}
      value={dataCellTextValue(model.value)}
      formatValue={() => model.displayText}
      placeholder=""
      className={cn(cellClassName, "text-sm")}
    />
  )
}

function ArrayTableCellEditor({
  path,
  column,
  onClose,
  cellProps,
}: {
  path: string
  column: Column
  onClose: () => void
  cellProps: React.HTMLAttributes<HTMLElement>
}) {
  return (
    <ArrayTableSelectCellEditor
      path={path}
      column={column}
      onClose={onClose}
      cellProps={cellProps}
    />
  )
}

function ArrayTableSelectCellEditor({
  path,
  column,
  onClose,
  cellProps,
}: {
  path: string
  column: Column
  onClose: () => void
  cellProps: React.HTMLAttributes<HTMLElement>
}) {
  const { control } = useFormContext()
  const { field } = useController({ control, name: path })

  return (
    <div
      {...cellProps}
      onKeyDown={(event) => {
        if (event.key === "Escape" || event.key === "Enter") {
          event.preventDefault()
          onClose()
        }
      }}
    >
      <ScalarControl
        kind={column.kind}
        schema={column.schema}
        field={{
          ...field,
          onBlur: () => {
            field.onBlur()
            onClose()
          },
        }}
        compact
        nullable={column.nullable}
      />
    </div>
  )
}

import type { DataCellKind } from "@/components/ui/data-cell"
import {
  enumLabel,
  enumValueEquals,
} from "@/components/json-form/scalar-control"
import type { Column } from "@/components/json-form/schema-model"

export type ArrayTableDataCellKind = Exclude<DataCellKind, "select">

export function formatArrayTableCellValue({
  value,
  column,
}: {
  value: unknown
  column: Column
}) {
  if (value == null || value === "") return "—"
  if (column.kind === "enum") {
    const option = column.schema.enum?.find((candidate) =>
      enumValueEquals(candidate, value)
    )
    return option === undefined ? enumLabel(value) : enumLabel(option)
  }
  if (typeof value === "number")
    return Number.isFinite(value) ? String(value) : "—"
  if (typeof value === "boolean") return value ? "True" : "False"
  return String(value)
}

export function dataCellKindForColumn(column: Column): ArrayTableDataCellKind {
  if (column.kind === "number" || column.kind === "integer") return column.kind
  if (column.kind === "boolean") return "boolean"
  if (column.schema.format === "date-time") return "date-time"
  if (column.schema.format === "date") return "date"
  if (column.schema.format === "time") return "time"
  return "text"
}

